   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "ord_numero",
     "legacy": "ord_numero"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "ord_empresa",
